import { Effect, FileSystem, Path } from 'effect'
import { buildContext, type ContextItem, type ContextTarget } from './context-bundle'
import { type BadMarkers, IoError } from './errors'
import { applyMarkedBlock, type Markers, renderMarkedBlock } from './marked-block'
import type { Repo } from './ops/repo'

export const startMarker = '<!-- netherite:context:start -->'
export const endMarker = '<!-- netherite:context:end -->'

const contextMarkers: Markers = {
  start: startMarker,
  end: endMarker,
  notice:
    '<!-- Generated by `netherite context sync` from context items. Edits between these markers are overwritten. -->',
}

/** The instruction file each target writes, relative to the workspace root. `mcp` has no file. */
export const targetFiles = { claude: 'CLAUDE.md', agents: 'AGENTS.md' } as const

export type SyncTarget = keyof typeof targetFiles

export type SyncStatus =
  /** The file was written (or, in check mode, would be). */
  | 'updated'
  | 'created'
  /** Already what sync would write. */
  | 'unchanged'

export interface TargetReport {
  readonly target: SyncTarget
  readonly path: string
  readonly status: SyncStatus
  /** Whether sync would change the file. In check mode this is what makes the check fail. */
  readonly stale: boolean
  readonly included: ReadonlyArray<ContextItem>
  /** Wanted but over the budget, highest priority first. */
  readonly omitted: ReadonlyArray<ContextItem>
  /** Estimated tokens in the block. */
  readonly tokens: number
  readonly budget: number
}

export interface SyncReport {
  readonly targets: ReadonlyArray<TargetReport>
  /** True when any target is stale. */
  readonly stale: boolean
}

export interface SyncOptions {
  /** Only report; write nothing. */
  readonly check?: boolean
  /** Sync only these targets. Default: the config's `context.targets`. */
  readonly targets?: ReadonlyArray<ContextTarget>
  /** Override the config's token budget. */
  readonly budget?: number
}

/** The block's text, markers included, in the file's line ending. */
export const renderBlock = (text: string, eol = '\n') =>
  renderMarkedBlock(contextMarkers, text, eol)

/** `applyMarkedBlock` for the context block. */
export const applyBlock = (path: string, existing: string | null, text: string) =>
  applyMarkedBlock(contextMarkers, path, existing, text)

const io =
  (path: string, operation: string) => (cause: import('effect').PlatformError.PlatformError) =>
    new IoError({ path, operation, cause })

/**
 * Renders the context bundle into `CLAUDE.md` and `AGENTS.md` between markers (ADR-00013). Each
 * target gets the items meant for it, kept within the token budget. With `check`, nothing is
 * written and the report says which files are out of date. Only writes files; never commits.
 */
export const syncContext = (repo: Repo, options: SyncOptions = {}) =>
  Effect.gen(function* () {
    const fs = yield* FileSystem.FileSystem
    const p = yield* Path.Path
    const { config } = repo.workspace
    const budget = options.budget ?? config.context.budget
    const wanted = (options.targets ?? config.context.targets).filter(
      (t): t is SyncTarget => t in targetFiles,
    )

    const targets: TargetReport[] = []
    for (const target of wanted) {
      const path = targetFiles[target]
      const file = p.join(repo.workspace.root, path)
      const bundle = buildContext(repo.index, { budget, target })

      const exists = yield* fs.exists(file).pipe(Effect.mapError(io(path, 'check')))
      const before = exists
        ? yield* fs.readFileString(file).pipe(Effect.mapError(io(path, 'read')))
        : null
      const after = yield* Effect.try({
        try: () => applyBlock(path, before, bundle.text),
        catch: (e) => e as BadMarkers,
      })

      const stale = after !== null && after !== before
      if (stale && options.check !== true) {
        const temp = p.join(p.dirname(file), `.${p.basename(file)}.${crypto.randomUUID()}.tmp`)
        yield* fs.writeFileString(temp, after).pipe(Effect.mapError(io(path, 'write')))
        yield* fs.rename(temp, file).pipe(
          Effect.mapError(io(path, 'replace')),
          Effect.tapError(() => fs.remove(temp, { force: true }).pipe(Effect.ignore)),
        )
      }
      targets.push({
        target,
        path,
        status: !stale ? 'unchanged' : before === null ? 'created' : 'updated',
        stale,
        included: bundle.included,
        omitted: bundle.omitted,
        tokens: bundle.tokens,
        budget: bundle.budget,
      })
    }
    return { targets, stale: targets.some((t) => t.stale) } satisfies SyncReport
  })
